INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Masalah: Bahasa Khmer Terlihat Menakutkan$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$Bahasa Khmer, bahasa resmi Kamboja, memakai aksara sendiri yang terlihat rumit dan pengucapannya asing di telinga orang Indonesia. Banyak wisatawan akhirnya hanya mengandalkan bahasa Inggris, padahal penduduk lokal di pasar, tuk-tuk, dan desa sangat menghargai usaha wisatawan yang menyapa dalam bahasa mereka. Kabar baiknya: untuk sapaan dasar, kamu tidak perlu bisa membaca aksara Khmer sama sekali.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Penjelasan: Sapaan Khmer Memakai Penanda Gender$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$Ciri khas sapaan Khmer adalah partikel sopan di akhir kalimat yang berbeda menurut gender pembicara: pria memakai 'baat', wanita memakai 'chaa'. Jadi 'terima kasih' yang diucapkan pria adalah 'awkun baat', sedangkan wanita mengucapkan 'awkun chaa'. Salam umumnya adalah 'choum reap sour' (halo/selamat) yang bisa dipakai kapan saja.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Alat yang Dibutuhkan$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$t$Aplikasi kamus Khmer-Indonesia/Inggris$t$, $t$Catatan kecil frasa penting$t$, $t$Aplikasi text-to-speech Khmer untuk melatih telinga$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Langkah: Sapaan Inti yang Wajib Dihafal$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$t$Choum reap sour: halo / selamat (umum)$t$, $t$Choum reap leah: selamat tinggal$t$, $t$Awkun (baat/chaa): terima kasih$t$, $t$Som toh: maaf / permisi$t$, $t$Baht (pria) / Chaa (wanita): ya (sopan)$t$, $t$Oht te: tidak$t$, $t$Tlai ponmaan: berapa harganya?$t$, $t$Sdai: enak / lezat$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $t$Risiko dan Kesalahan Umum$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$t$Tertukar partikel gender: pria yang memakai 'chaa' akan terdengar aneh$t$, $t$Mengucapkan 'choum reap sour' terlalu cepat sehingga terdengar seperti satu bunyi$t$, $t$Mengandalkan transliterasi Inggris yang tidak konsisten antar sumber$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $t$Pemeriksaan Hasil$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $t$Uji dirimu: bisakah kamu menyapa, berterima kasih, bertanya harga, dan pamit tanpa melihat catatan? Jika penjual di pasar menjawab dengan senyum dan bahasa Khmer, sapaanmu sudah benar. Langkah lanjut: pelajari angka 1-10 Khmer agar bisa tawar-menawar.$t$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Masalah: Jari Tiba-tiba Kebas dan Berdenyut$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$Kesemutan di jari tangan adalah sensasi kebas, geli, atau seperti ditusuk jarum halus. Umumnya muncul setelah tangan tertekan lama, misalnya tertindih saat tidur atau menggenggam ponsel terlalu lama. Pada kebanyakan kasus sensasinya hilang sendiri dalam beberapa menit, tetapi kesemutan yang sering kambuh atau tidak hilang perlu diperhatikan.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Penjelasan: Saraf Terjepit Sementara$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$Kesemutan terjadi ketika saraf atau aliran darah ke jari terganggu sementara. Saraf median di pergelangan tangan, saraf ulnaris di siku, dan saraf radial di lengan atas adalah jalur yang paling sering tertekan. Selain tekanan mekanis, kekurangan vitamin B12, kadar gula darah tinggi, dan gangguan tiroid juga bisa memicu kesemutan berulang.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Persiapan dan Alat Bantu$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$t$Bantal kecil untuk menopang lengan saat tidur$t$, $t$Catatan pola kesemutan (kapan muncul, jari mana, berapa lama)$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Langkah Pertolongan Mandiri$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$t$Goyang dan kepalkan tangan perlahan untuk melancarkan aliran darah$t$, $t$Ubah posisi: jangan menindih tangan saat tidur, longgarkan jam atau gelang$t$, $t$Istirahatkan tangan dari aktivitas berulang seperti mengetik atau memegang ponsel$t$, $t$Kompres hangat pada area yang kesemutan selama 10-15 menit$t$, $t$Lakukan peregangan jari dan pergelangan beberapa kali sehari$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $t$Risiko dan Kapan Harus ke Dokter$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$t$Kesemutan hanya di satu sisi tubuh disertai wajah mencong atau bicara pelo: segera ke IGD$t$, $t$Kesemutan tidak hilang lebih dari satu jam atau makin sering kambuh$t$, $t$Disertai kelemahan menggenggam, jari sulit digerakkan, atau nyeri menjalar ke lengan$t$, $t$Terjadi setelah cedera atau benturan keras$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $t$Penutup dan Disclaimer$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $t$Artikel ini adalah informasi umum dan bukan pengganti nasihat medis. Jika kesemutan sering kambuh, menyebar, atau disertai gejala lain, konsultasikan ke dokter untuk pemeriksaan saraf lebih lanjut.$t$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Apa Itu Selat$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$Selat adalah perairan sempit yang menghubungkan dua perairan lebih besar dan memisahkan dua daratan. Karena menjadi jalur pelayaran tersingkat, selat-selat strategis selalu diperebutkan dan menjadi penentu kekuatan ekonomi maupun militer sejak zaman kuno hingga kini.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Selat Malaka: Urat Nadi Asia$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$Selat Malaka menghubungkan Samudra Hindia dengan Laut Cina Selatan dan dilalui sekitar seperempat perdagangan dunia, termasuk sebagian besar minyak mentah menuju Asia Timur. Indonesia, Malaysia, dan Singapura berbagi pengelolaannya, sehingga keamanan selat ini menjadi kepentingan global.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Selat Gibraltar dan Hormuz$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $t$Selat Gibraltar, selebar hanya 14 kilometer, adalah pintu masuk Laut Tengah dari Atlantik dan dijaga ketat Spanyol serta Inggris. Selat Hormuz di Teluk Persia bahkan lebih vital: sekitar seperlima konsumsi minyak dunia melewatinya, sehingga ketegangan politik di sana langsung mengguncang harga minyak global.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Bosporus dan Dardanella$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $t$Dua selat di Turki ini menghubungkan Laut Hitam dengan Laut Tengah dan diatur oleh Konvensi Montreux 1936. Turki mengendalikan lalu lintas kapal perang yang melintas, menjadikan selat ini alat diplomasi penting, terutama saat konflik melibatkan negara-negara Laut Hitam.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $t$Mengapa Selat Menjadi Rebutan$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $t$Siapa menguasai selat strategis, ia menguasai arus barang dan energi dunia. Karena itu banyak selat menjadi titik sengketa: perebutan kedaulatan, pembajakan, hingga perlombaan membangun pangkalan militer di sekitarnya. Memahami peta selat berarti memahami peta kekuasaan dunia.$t$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Energi dari Inti Atom$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$PLTN menghasilkan listrik dari fisi nuklir: inti atom uranium-235 dibelah oleh neutron sehingga melepaskan energi panas yang sangat besar. Satu pelet uranium seukuran penghapus pensil setara dengan energi satu ton batu bara. Panas ini mendidihkan air menjadi uap yang memutar turbin generator listrik.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Cara Kerja Reaktor$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$Di dalam teras reaktor, batang bahan bakar uranium disusun di antara batang kendali yang menyerap neutron untuk mengatur laju reaksi. Air berfungsi ganda sebagai pendingin dan moderator yang memperlambat neutron. Sistem berlapis memastikan reaksi berhenti otomatis jika terjadi anomali.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Keunggulan PLTN$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $t$PLTN tidak menghasilkan emisi karbon saat beroperasi dan mampu menyala terus-menerus siang malam, berbeda dengan surya dan angin yang tergantung cuaca. Kebutuhan lahannya kecil dibanding pembangkit lain untuk daya yang sama, dan biaya bahan bakarnya relatif murah.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Risiko dan Perdebatan$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $t$Kecelakaan seperti Chernobyl 1986 dan Fukushima 2011 menunjukkan bahwa kegagalan sistem bisa berdampak luas dan lama. Limbah radioaktif tingkat tinggi harus disimpan aman selama ribuan tahun, dan teknologi yang sama bisa disalahgunakan untuk senjata. Inilah inti perdebatan pro dan kontra PLTN di banyak negara termasuk Indonesia.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $t$Masa Depan: Reaktor Modular Kecil$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $t$Generasi baru reaktor modular kecil (SMR) dirancang lebih aman dengan sistem pendingin pasif yang tidak butuh listrik eksternal saat darurat. Banyak negara melihat SMR sebagai jembatan menuju energi bersih, sementara penolakan publik tetap menjadi tantangan terbesarnya.$t$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Tujuan Pembelajaran$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$Setelah mempelajari materi ini, siswa mampu menyebutkan dan menulis cardinal numbers dan ordinal numbers dengan benar, serta menggunakannya dalam konteks tahun, tanggal, jam, dan harga.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Cardinal Numbers: Angka Menghitung$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$Cardinal numbers adalah angka untuk menghitung: one, two, three, dan seterusnya. Pola pentingnya: belasan memakai akhiran -teen (thirteen sampai nineteen), puluhan memakai -ty (twenty, thirty, forty), dan seratus adalah one hundred. Perhatikan forty (bukan fourty) dan pengucapan thirteen vs thirty yang sering tertukar.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Contoh Cardinal Numbers$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $t$1-10: one, two, three, four, five, six, seven, eight, nine, ten. 11-19: eleven, twelve, thirteen sampai nineteen. Puluhan: twenty, thirty, forty, fifty, sixty, seventy, eighty, ninety. 100 = one hundred, 1.000 = one thousand, 1.000.000 = one million.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Ordinal Numbers: Angka Urutan$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $t$Ordinal numbers menyatakan urutan: first (1st), second (2nd), third (3rd), lalu pola umum tambah -th seperti fourth, fifth, sixth. Pengecualian: eighth (satu t), ninth (tanpa e), twelfth (f menjadi v). Angka 21 adalah twenty-first, 32 adalah thirty-second.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $t$Membaca Tahun, Tanggal, dan Jam$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$t$Tahun 1998 dibaca nineteen ninety-eight; tahun 2005 dibaca two thousand and five$t$, $t$Tanggal 17 Agustus: the seventeenth of August atau August seventeenth$t$, $t$Jam 07.30: half past seven; jam 07.15: a quarter past seven$t$, $t$Harga Rp25.000: twenty-five thousand rupiah$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $t$Latihan dan Kunci Jawaban$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$t$Tuliskan angka 13, 30, 40, dan 100 dalam bahasa Inggris$t$, $t$Ubah menjadi ordinal: 1, 2, 3, 5, 8, 9, 12, 21$t$, $t$Bacalah tahun 1945 dan 2026 dalam bahasa Inggris$t$, $t$Tuliskan jam 08.45 dan tanggal 20 Mei dalam bahasa Inggris$t$, $t$Kunci: thirteen, thirty, forty, one hundred; first, second, third, fifth, eighth, ninth, twelfth, twenty-first; nineteen forty-five; twenty twenty-six; a quarter to nine; the twentieth of May$t$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Tujuan Pembelajaran$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$Setelah belajar, siswa kelas 2 mampu menjelaskan apa itu dongeng, menyebutkan jenis-jenis dongeng, dan menemukan pesan baik dari sebuah dongeng.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Apa Itu Dongeng$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$Dongeng adalah cerita khayalan yang diwariskan turun-temurun untuk menghibur sekaligus mengajarkan kebaikan. Dongeng biasanya memiliki tokoh hewan yang bisa berbicara, benda ajaib, atau kejadian luar biasa yang tidak mungkin terjadi di dunia nyata.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Jenis-jenis Dongeng$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$t$Fabel: dongeng tentang hewan, contohnya Kancil dan Buaya$t$, $t$Legenda: cerita asal-usul tempat atau benda, contohnya Malin Kundang$t$, $t$Mite: cerita tentang dewa dan makhluk sakti zaman dahulu$t$, $t$Sage: kisah kepahlawanan, contohnya Hang Tuah$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Tokoh, Watak, dan Pesan Moral$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $t$Tokoh dongeng ada yang baik hati, jujur, dan penolong, ada pula yang jahat, serakah, dan suka berbohong. Dari kelakuan tokoh inilah kita bisa mengambil pelajaran: tokoh baik biasanya berakhir bahagia, tokoh jahat mendapat hukuman. Pesan moral adalah nasihat baik yang tersembunyi di dalam cerita, misalnya dongeng Malin Kundang mengajarkan kita untuk selalu menghormati orang tua.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $t$Latihan$t$));
